export default async function payload(
  {
    notification,
    baseId,
    tableId,
    recordsHook,
    fieldsHook,
    previous,
    response,
    record,
    records,
    offset,
  },
  ctx,
) {
  if (!/^app[A-Za-z0-9]{14}$/.test(baseId) || !/^tbl[A-Za-z0-9]{14}$/.test(tableId))
    throw Error("Configure Airtable base and table IDs");
  const hook = notification?.webhook?.id;
  if (
    notification?.base?.id !== baseId ||
    ![recordsHook, fieldsHook].includes(hook) ||
    !/^ach[A-Za-z0-9]{14}$/.test(hook)
  )
    throw Error("Unexpected Airtable notification");
  const key = "airtable-pdf-cursor:" + hook;
  let s = previous ?? { cursor: (await ctx.state.get(key)) ?? 1, queue: [], index: 0 };
  if (s.awaiting === "fetch") {
    if (
      !response ||
      !Array.isArray(response.payloads) ||
      !Number.isSafeInteger(response.cursor) ||
      typeof response.mightHaveMore !== "boolean"
    )
      throw Error("Invalid webhook payload response");
    if (response.payloads.some((p) => p.error)) throw Error("Airtable webhook needs recreation");
    s = {
      ...s,
      awaiting: null,
      nextCursor: response.cursor,
      mightHaveMore: response.mightHaveMore,
      payloads: response.payloads,
      payloadIndex: 0,
      queue: [],
      index: 0,
      offset: null,
    };
  } else if (s.awaiting === "get") {
    if (!record?.id || record.id !== s.expectedRecord) throw Error("Unexpected Airtable record");
    s.awaiting = null;
    s.queue = [{ kind: "row", record, eventId: s.eventId }];
    s.index = 0;
  } else if (s.awaiting === "list") {
    if (!Array.isArray(records)) throw Error("Invalid Airtable record page");
    s.awaiting = null;
    s.queue = records.map((record) => ({
      kind: "field",
      fieldId: s.fieldIds[s.fieldIndex],
      record,
      eventId: s.eventId,
    }));
    s.index = 0;
    s.offset = offset ?? null;
    if (!s.offset) s.fieldIndex++;
  }
  for (;;) {
    if (s.index < s.queue.length) {
      const job = s.queue[s.index++];
      return { state: s, step: "job", job, endpoint: "unused", recordId: "unused", offset: null };
    }
    if (s.rowIds && s.rowIndex < s.rowIds.length) {
      s.expectedRecord = s.rowIds[s.rowIndex++];
      s.awaiting = "get";
      return {
        state: s,
        step: "get",
        job: {},
        endpoint: "unused",
        recordId: s.expectedRecord,
        offset: null,
      };
    }
    if (s.fieldIds?.length && (s.offset || s.fieldIndex < s.fieldIds.length)) {
      const requestOffset = s.offset ?? null;
      s.awaiting = "list";
      return {
        state: s,
        step: "list",
        job: {},
        endpoint: "unused",
        recordId: "unused",
        offset: requestOffset,
      };
    }
    if (s.payloadIndex < (s.payloads ?? []).length) {
      delete s.rowIds;
      delete s.fieldIds;
      const i = s.payloadIndex++,
        p = s.payloads[i],
        change = p.changedTablesById?.[tableId];
      if (p.actionMetadata?.source !== "client" || !change) continue;
      s.eventId = hook + ":" + (s.nextCursor - s.payloads.length + i);
      if (hook === recordsHook) {
        s.rowIds = Object.keys(change.changedRecordsById ?? {});
        s.rowIndex = 0;
        continue;
      }
      const ids = [
        ...Object.keys(change.createdFieldsById ?? {}),
        ...Object.keys(change.changedFieldsById ?? {}),
      ];
      if (!ids.length) continue;
      s.fieldIds = ids;
      s.fieldIndex = 0;
      s.offset = null;
      continue;
    }
    if (s.nextCursor !== undefined) {
      await ctx.state.set(key, s.nextCursor);
      s.cursor = s.nextCursor;
      const more = s.mightHaveMore;
      delete s.nextCursor;
      delete s.payloads;
      if (!more)
        return {
          state: s,
          step: "done",
          job: {},
          endpoint: "unused",
          recordId: "unused",
          offset: null,
        };
    }
    s.awaiting = "fetch";
    return {
      state: s,
      step: "fetch",
      job: {},
      endpoint:
        "/v0/bases/" + baseId + "/webhooks/" + hook + "/payloads?limit=1&cursor=" + s.cursor,
      recordId: "unused",
      offset: null,
    };
  }
}

