export default async function next(
  { job, tables, tableId, previous, acknowledge, resolution },
  ctx,
) {
  const table = tables.find((x) => x.id === tableId);
  if (!table) throw Error("Table schema missing");
  const record = job.record;
  if (!record?.id || !record.fields) throw Error("Invalid record");
  const key = job.eventId + ":" + record.id + ":" + (job.fieldId ?? "row");
  let state = previous?.key === key ? previous : { key, index: 0 };
  const fields =
    job.kind === "field"
      ? table.fields.filter((x) => x.id === job.fieldId)
      : table.fields.filter((x) => x.description && !record.fields[x.name]);
  const url = record.fields.File?.[0]?.url;
  if (!url)
    return {
      state,
      more: false,
      field: {},
      recordId: record.id,
      pdfUrl: "https://example.invalid",
    };
  while (state.index < fields.length) {
    const f = fields[state.index++];
    if (!f.description || f.name === "File") continue;
    const itemKey = "airtable-pdf:" + job.eventId + ":" + record.id + ":" + f.id;
    let current = await ctx.state.get(itemKey);
    if (current?.status === "pending") {
      if (acknowledge !== itemKey || !["confirmed", "absent"].includes(resolution))
        throw Error("Inspect pending " + itemKey);
      current = resolution === "confirmed" ? { status: "done" } : null;
      await ctx.state.set(itemKey, current);
    }
    if (current?.status === "done") continue;
    return {
      state,
      more: true,
      field: { name: f.name, id: f.id, type: f.type, prompt: f.description, key: itemKey },
      recordId: record.id,
      pdfUrl: url,
    };
  }
  return { state, more: false, field: {}, recordId: record.id, pdfUrl: url };
}

