export default async function reserve({ field, recordId, result }, ctx) {
  if (!field?.key || !field?.name || typeof result !== "string")
    throw Error("Invalid model output");
  await ctx.state.set(field.key, { status: "pending" });
  return { key: field.key, records: [{ id: recordId, fields: { [field.name]: result.trim() } }] };
}

