export default async function confirm({ key, recordId, records }, ctx) {
  if (!Array.isArray(records) || records.length !== 1 || records[0].id !== recordId)
    throw Error("Unknown Airtable write result");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}
